param(
    [string]$TitlePrefix = 'zapret:'
)

$ErrorActionPreference = 'SilentlyContinue'

Add-Type -AssemblyName System.Drawing
Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class SorapretWindowIcon {
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    public static extern IntPtr SendMessage(IntPtr hWnd, uint msg, IntPtr wParam, IntPtr lParam);
}
'@

# Embedded user-provided Nyan Cat artwork, reduced for a crisp taskbar icon.
$jpgBase64 = ''

$bytes = [Convert]::FromBase64String($jpgBase64)
$stream = New-Object IO.MemoryStream(,$bytes)
$source = [Drawing.Image]::FromStream($stream)
$bitmap = New-Object Drawing.Bitmap 64,64
$graphics = [Drawing.Graphics]::FromImage($bitmap)
$graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
$graphics.DrawImage($source, 0, 0, 64, 64)
$iconHandle = $bitmap.GetHicon()

$target = $null
for ($attempt = 0; $attempt -lt 50 -and -not $target; $attempt++) {
    $target = Get-Process winws -ErrorAction SilentlyContinue |
        Where-Object { $_.MainWindowHandle -ne 0 -and $_.MainWindowTitle -like "$TitlePrefix*" } |
        Sort-Object StartTime -Descending |
        Select-Object -First 1
    if (-not $target) { Start-Sleep -Milliseconds 200 }
}

if ($target) {
    [void][SorapretWindowIcon]::SendMessage($target.MainWindowHandle, 0x0080, [IntPtr]1, $iconHandle)
    [void][SorapretWindowIcon]::SendMessage($target.MainWindowHandle, 0x0080, [IntPtr]0, $iconHandle)

    # Keep the icon handle alive while the target window exists.
    while (Get-Process -Id $target.Id -ErrorAction SilentlyContinue) {
        Start-Sleep -Seconds 2
    }
}

$graphics.Dispose()
$bitmap.Dispose()
$source.Dispose()
$stream.Dispose()
